#![allow(unused)]
use vstd::prelude::*;
use builtin::*;
use builtin::seq::*;

/// Given three vectors of equal length, returns a vector where each element is
/// taken from `src` if corresponding `mask` is true, otherwise from `dst`.
#[verifier(
    // Precondition: all three vectors have the same length
    requires(dst.len() == src.len()),
    requires(src.len() == mask.len()),

    // Postcondition: output length equals input length
    ensures(|result: Vec<T>| result.len() == dst.len()),

    // Postcondition: for all indices i, output[i] = if mask[i] { src[i] } else { dst[i] }
    ensures(|result: Vec<T>| 
        forall<i: usize> 0 <= i && i < result.len() ==>
            result[i] == if mask[i] { src[i] } else { dst[i] }),

    // Since function uses iteration, we state decreases on length for internal reasoning
    decreases(dst.len())
)]
fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    dst.into_iter()
        .zip(src.into_iter())
        .zip(mask.into_iter())
        .map(|((d, s), m)| if m { s } else { d })
        .collect()
}